import{_ as t,a0 as l,w as o,s as r,ao as d,I as n,x as a,a1 as p,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用 snapcraft 將 snap 包發佈到商店 | LCTT x X-CMD","titleTemplate":false,"description":"使用 snapcraft 將 snap 包發佈到商店 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 snapcraft 將 snap 包發佈到商店 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 snapcraft 將 snap 包發佈到商店 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20161115 Making your snaps available to the store using snapcraft","title":"使用 snapcraft 將 snap 包發佈到商店","tag":"201708","desc":""},"relativePath":"201708/20161115 Making your snaps available to the store using snapcraft.md","filePath":"[post].md"}'),c={name:"201708/20161115 Making your snaps available to the store using snapcraft.md"};function h(g,s,b,u,f,k){const e=l("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="使用-snapcraft-將-snap-包發佈到商店" tabindex="-1">使用 snapcraft 將 snap 包發佈到商店 <a class="header-anchor" href="#使用-snapcraft-將-snap-包發佈到商店" aria-label="Permalink to “使用 snapcraft 將 snap 包發佈到商店”">​</a></h1><p><img src="https://insights.ubuntu.com/wp-content/uploads/9be3/Snaps.jpg" alt="snaps"></p><p>Ubuntu Core 已經正式發佈（LCTT 譯註：指 2016 年 11 月發佈的 Ubuntu Snappy Core 16 ），也許是時候讓你的 snap 包進入商店了！</p><h3 id="交付和商店的概念" tabindex="-1">交付和商店的概念 <a class="header-anchor" href="#交付和商店的概念" aria-label="Permalink to “交付和商店的概念”">​</a></h3><p>首先回顧一下我們是怎麼通過商店管理 snap 包的吧。</p><p>每次你上傳 snap 包，商店都會為其分配一個修訂版本號，並且商店中針對特定 snap 包 的版本號都是唯一的。</p><p>但是第一次上傳 snap 包的時候，我們首先要為其註冊一個還沒有被使用的名字，這很容易。</p><p>商店中所有的修訂版本都可以釋放到多個通道中，這些通道只是概念上定義的，以便給用户一個穩定或風險等級的參照，這些通道有:</p><ul><li>穩定（stable）</li><li>候選（candidate）</li><li>測試（beta）</li><li>邊緣（edge）</li></ul><p>理想情況下，如果我們設置了 CI/CD 過程，那麼每天或在每次更新源碼時都會將其推送到邊緣通道。在此過程中有兩件事需要考慮。</p><p>首先在開始的時候，你最好製作一個不受限制的 snap 包，因為在這種新範例下，snap 包的大部分功能都能不受限制地工作。考慮到這一點，你的項目開始時 <code>confinement</code> 將被設置為 <code>devmode</code>（LCTT 譯註：這是 <code>snapcraft.yaml</code> 中的一個鍵及其可選值）。這使得你在開發的早期階段，仍然可以讓你的 snap 包進入商店。一旦所有的東西都得到了 snap 包運行的安全模型的充分支持，那麼就可以將 <code>confinement</code> 修改為 <code>strict</code>。</p><p>好了，假設你在限制方面已經做好了，並且也開始了一個對應邊緣通道的 CI/CD 過程，但是如果你也想確保在某些情況下，早期版本 master 分支新的迭代永遠也不會進入穩定或候選通道，那麼我們可以使用 <code>gadge</code> 設置。如果 snap 包的 <code>gadge</code> 設置為 <code>devel</code> （LCTT注：這是 <code>snapcraft.yaml</code> 中的一個鍵及其可選值），商店將會永遠禁止你將 snap 包釋放到穩定和候選通道。</p><p>在這個過程中，我們有時可能想要發佈一個修訂版本到測試通道，以便讓有些用户更願意去跟蹤它（一個好的發佈管理流程應該比一個隨機的日常構建更有用）。這個階段結束後，如果希望人們仍然能保持更新，我們可以選擇關閉測試通道，從一個特定的時間點開始我們只計劃發佈到候選和穩定通道，通過關閉測試通道我們將使該通道跟隨穩定列表中的下一個開放通道，在這裏是候選通道。而如果候選通道跟隨的是穩定通道後，那麼最終得到是穩定通道了。</p><h3 id="進入-snapcraft" tabindex="-1">進入 Snapcraft <a class="header-anchor" href="#進入-snapcraft" aria-label="Permalink to “進入 Snapcraft”">​</a></h3><p>那麼所有這些給定的概念是如何在 snapcraft 中配合使用的？首先我們需要登錄:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft login</span></span>
<span class="line"><span>Enter your Ubuntu One SSO credentials.</span></span>
<span class="line"><span>Email: sxxxxx.sxxxxxx@canonical.com</span></span>
<span class="line"><span>Password: **************</span></span>
<span class="line"><span>Second-factor auth: 123456</span></span></code></pre></div><p>在登錄之後，我們就可以開始註冊 snap 了。例如，我們想要註冊一個虛構的 snap 包 awesome-database：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft register awesome-database</span></span>
<span class="line"><span>We always want to ensure that users get the software they expect</span></span>
<span class="line"><span>for a particular name.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If needed, we will rename snaps to ensure that a particular name</span></span>
<span class="line"><span>reflects the software most widely expected by our community.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For example, most people would expect ‘thunderbird’ to be published by</span></span>
<span class="line"><span>Mozilla. They would also expect to be able to get other snaps of</span></span>
<span class="line"><span>Thunderbird as &#39;thunderbird-sergiusens&#39;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Would you say that MOST users will expect &#39;a&#39; to come from</span></span>
<span class="line"><span>you, and be the software you intend to publish there? [y/N]: y</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are now the publisher for &#39;awesome-database&#39;</span></span></code></pre></div><p>假設我們已經構建了 snap 包，接下來我們要做的就是把它上傳到商店。我們可以在同一個命令中使用快捷方式和 <code>--release</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft push awesome-databse_0.1_amd64.snap --release edge</span></span>
<span class="line"><span>Uploading awesome-database_0.1_amd64.snap [=================] 100%</span></span>
<span class="line"><span>Processing....</span></span>
<span class="line"><span>Revision 1 of &#39;awesome-database&#39; created.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Channel    Version    Revision</span></span>
<span class="line"><span>stable     -          -</span></span>
<span class="line"><span>candidate  -          -</span></span>
<span class="line"><span>beta       -          -</span></span>
<span class="line"><span>edge       0.1        1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The edge channel is now open.</span></span></code></pre></div><p>如果我們試圖將其發佈到穩定通道，商店將會阻止我們：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft release awesome-database 1 stable</span></span>
<span class="line"><span>Revision 1 (devmode) cannot target a stable channel (stable, grade: devel)</span></span></code></pre></div><p>這樣我們不會搞砸，也不會讓我們的忠實用户使用它。現在，我們將最終推出一個值得發佈到穩定通道的修訂版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft push awesome-databse_0.1_amd64.snap</span></span>
<span class="line"><span>Uploading awesome-database_0.1_amd64.snap [=================] 100%</span></span>
<span class="line"><span>Processing....</span></span>
<span class="line"><span>Revision 10 of &#39;awesome-database&#39; created.</span></span></code></pre></div><p>注意，<ruby>版本號<rt>version</rt></ruby>（LCTT 譯註：這裏指的是 snap 包名中 <code>0.1</code> 這個版本號）只是一個友好的標識符，真正重要的是商店為我們生成的<ruby>修訂版本號<rt>Revision</rt></ruby>（LCTT 譯註：這裏生成的修訂版本號為 <code>10</code>）。現在讓我們把它釋放到穩定通道：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft release awesome-database 10 stable</span></span>
<span class="line"><span>Channel    Version    Revision</span></span>
<span class="line"><span>stable     0.1        10</span></span>
<span class="line"><span>candidate  ^          ^</span></span>
<span class="line"><span>beta       ^          ^</span></span>
<span class="line"><span>edge       0.1        10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The &#39;stable&#39; channel is now open.</span></span></code></pre></div><p>在這個針對我們正在使用架構最終的通道映射視圖中，可以看到邊緣通道將會被固定在修訂版本 10 上，並且測試和候選通道將會跟隨現在修訂版本為 10 的穩定通道。由於某些原因，我們決定將專注於穩定性並讓我們的 CI/CD 推送到測試通道。這意味着我們的邊緣通道將會略微過時，為了避免這種情況，我們可以關閉這個通道：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ snapcraft close awesome-database edge</span></span>
<span class="line"><span>Arch    Channel    Version    Revision</span></span>
<span class="line"><span>amd64   stable     0.1        10</span></span>
<span class="line"><span>        candidate  ^          ^</span></span>
<span class="line"><span>        beta       ^          ^</span></span>
<span class="line"><span>        edge       ^          ^</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The edge channel is now closed.</span></span></code></pre></div><p>在當前狀態下，所有通道都跟隨着穩定通道，因此訂閲了候選、測試和邊緣通道的人也將跟蹤穩定通道的改動。比如就算修訂版本 11 只發布到穩定通道，其他通道的人們也能看到它。</p><p>這個清單還提供了完整的體系結構視圖，在本例中，我們只使用了 amd64。</p><h3 id="獲得更多的信息" tabindex="-1">獲得更多的信息 <a class="header-anchor" href="#獲得更多的信息" aria-label="Permalink to “獲得更多的信息”">​</a></h3><p>有時過了一段時間，我們想知道商店中的某個 snap 包的歷史記錄和現在的狀態是什麼樣的，這裏有兩個命令，一個是直截了當輸出當前的狀態，它會給我們一個熟悉的結果:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ snapcraft status awesome-database</span></span>
<span class="line"><span>Arch    Channel    Version    Revision</span></span>
<span class="line"><span>amd64   stable     0.1        10</span></span>
<span class="line"><span>        candidate  ^          ^</span></span>
<span class="line"><span>        beta       ^          ^</span></span>
<span class="line"><span>        edge       ^          ^</span></span></code></pre></div><p>我們也可以通過下面的命令獲得完整的歷史記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ snapcraft history awesome-database</span></span>
<span class="line"><span>Rev.    Uploaded              Arch       Version    Channels</span></span>
<span class="line"><span>3       2016-09-30T12:46:21Z  amd64      0.1        stable*</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>2       2016-09-30T12:38:20Z  amd64      0.1        -</span></span>
<span class="line"><span>1       2016-09-30T12:33:55Z  amd64      0.1        -</span></span></code></pre></div><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>希望這篇文章能讓你對商店能做的事情有一個大概的瞭解，並讓更多的人開始使用它！</p><hr>`,38)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),p(e,{href:"https://insights.ubuntu.com/2016/11/15/making-your-snaps-available-to-the-store-using-snapcraft/"},{default:i(()=>[...s[0]||(s[0]=[a("https://insights.ubuntu.com/2016/11/15/making-your-snaps-available-to-the-store-using-snapcraft/",-1)])]),_:1})]),s[14]||(s[14]=n("p",null,[n("em",null,"譯者簡介：")],-1)),s[15]||(s[15]=n("blockquote",null,[n("p",null,[a("snapcraft.io 的釘子户，對 Ubuntu Core、Snaps 和 Snapcraft 有着濃厚的興趣，並致力於將這些還在快速發展的新技術通過翻譯或原創的方式介紹到中文世界。有興趣的小夥伴也可以關注譯者個人的公眾號： "),n("code",null,"Snapcraft"),a("，近期會在上面連載幾篇有關 Core snap 發佈策略、交付流程和驗證流程的文章，歡迎圍觀 :）")])],-1)),n("p",null,[s[5]||(s[5]=a("作者：",-1)),p(e,{href:"https://insights.ubuntu.com/author/sergio-schvezov/"},{default:i(()=>[...s[2]||(s[2]=[a("Sergio Schvezov",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),p(e,{href:"https://github.com/Snapcrafter"},{default:i(()=>[...s[3]||(s[3]=[a("Snapcrafter",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const v=t(c,[["render",h]]);export{C as __pageData,v as default};
